"use client";

import * as React from "react";
import { cva, type VariantProps } from "class-variance-authority";
import { cn } from "@/lib/utils";
import { ChevronLeft, ChevronRight } from "@/components/ui/icons";

// Date Picker: generated by UIX from the design system. Same variants and sizes as the Figma component.

const datePickerVariants = cva(
  "flex w-[292px] flex-col gap-3 p-5 bg-surface text-fg-primary border border-line-default shadow-lg rounded-xl",
  {
    variants: {
      type: {
        single: "",
        range: "",
      },
    },
    defaultVariants: {
      type: "single",
    },
  },
);

export interface DateRange {
  from?: Date;
  to?: Date;
}

function sameDay(a?: Date, b?: Date) {
  return !!a && !!b && a.getFullYear() === b.getFullYear() && a.getMonth() === b.getMonth() && a.getDate() === b.getDate();
}

export interface DatePickerProps
  extends Omit<React.HTMLAttributes<HTMLDivElement>, "onChange" | "defaultValue">,
    VariantProps<typeof datePickerVariants> {
  /** Selected day, or the start and end of a range (controlled). */
  value?: DateRange;
  defaultValue?: DateRange;
  onValueChange?: (value: DateRange) => void;
  /** Month shown first. */
  month?: Date;
  /** 0 = Sunday, 1 = Monday. */
  weekStartsOn?: 0 | 1;
  /** BCP 47 tag for month and weekday names. */
  locale?: string;
  /** Summary and Cancel / Apply buttons under the calendar. */
  showFooter?: boolean;
  onCancel?: () => void;
  onApply?: (value: DateRange) => void;
}

const DatePicker = React.forwardRef<HTMLDivElement, DatePickerProps>(
  ({ className, type, value, defaultValue, onValueChange, month, weekStartsOn = 1, locale, showFooter = false, onCancel, onApply, ...props }, ref) => {
    const [inner, setInner] = React.useState<DateRange>(defaultValue ?? {});
    const current = value ?? inner;
    const range = type === "range";
    const [view, setView] = React.useState(month ?? current.from ?? new Date());
    const first = new Date(view.getFullYear(), view.getMonth(), 1);
    const lead = (first.getDay() - weekStartsOn + 7) % 7;
    const days = Array.from({ length: 42 }, (_, index) => new Date(first.getFullYear(), first.getMonth(), 1 - lead + index));
    const weekdays = Array.from({ length: 7 }, (_, index) => new Date(2024, 0, 7 + ((weekStartsOn + index) % 7)).toLocaleDateString(locale, { weekday: "short" }).slice(0, 2));
    const today = new Date();
    const choose = (day: Date) => {
      const next: DateRange = range && current.from && !current.to && day.getTime() >= current.from.getTime() ? { from: current.from, to: day } : { from: day };
      setInner(next);
      onValueChange?.(next);
    };
    const format = (day: Date) => day.toLocaleDateString(locale, { month: "short", day: "numeric", year: "numeric" });
    const summary = current.from ? (current.to ? format(current.from) + " – " + format(current.to) : format(current.from)) : "No date selected";
    return (
      <div data-slot="date-picker" data-kind="overlay" ref={ref} role="group" aria-label="Calendar" className={cn(datePickerVariants({ type }), className)} {...props}>
        <div className="flex items-center justify-between">
          <button type="button" aria-label="Previous month" onClick={() => setView(new Date(view.getFullYear(), view.getMonth() - 1, 1))} className="inline-flex shrink-0 cursor-pointer items-center justify-center size-8 rounded-sm text-icon-secondary hover:bg-subtle focus-visible:outline-none focus-visible:ring-3 focus-visible:ring-line-focus [&_svg]:size-4">
            <ChevronLeft aria-hidden />
          </button>
          <p aria-live="polite" className="text-title-small text-fg-primary">{view.toLocaleDateString(locale, { month: "long", year: "numeric" })}</p>
          <button type="button" aria-label="Next month" onClick={() => setView(new Date(view.getFullYear(), view.getMonth() + 1, 1))} className="inline-flex shrink-0 cursor-pointer items-center justify-center size-8 rounded-sm text-icon-secondary hover:bg-subtle focus-visible:outline-none focus-visible:ring-3 focus-visible:ring-line-focus [&_svg]:size-4">
            <ChevronRight aria-hidden />
          </button>
        </div>
        <div className="grid grid-cols-7 place-items-center">
          {weekdays.map((name, index) => (
            <span key={index} aria-hidden className="inline-flex items-center justify-center h-[28px] w-[36px] text-label-small text-fg-tertiary">
              {name}
            </span>
          ))}
        </div>
        <div className="grid grid-cols-7 place-items-center gap-0-5">
          {days.map((day) => {
            const edge = sameDay(day, current.from) || sameDay(day, current.to);
            const band = range && !!current.from && !!current.to && day.getTime() > current.from.getTime() && day.getTime() < current.to.getTime();
            return (
              <button
                key={day.getTime()}
                type="button"
                aria-label={day.toLocaleDateString(locale, { dateStyle: "long" })}
                aria-pressed={edge}
                aria-current={sameDay(day, today) ? "date" : void 0}
                data-selected={edge ? "" : void 0}
                data-range={band ? "" : void 0}
                data-outside={day.getMonth() !== view.getMonth() ? "" : void 0}
                onClick={() => choose(day)}
                className="inline-flex cursor-pointer items-center justify-center rounded-full size-[36px] text-body-small text-fg-primary hover:bg-subtle focus-visible:outline-none focus-visible:ring-3 focus-visible:ring-line-focus data-[outside]:text-fg-tertiary data-[range]:bg-brand-subtle data-[range]:hover:bg-brand-subtle data-[selected]:bg-brand data-[selected]:text-fg-on-brand data-[selected]:hover:bg-brand-hover aria-[current=date]:border aria-[current=date]:border-line-brand"
              >
                {day.getDate()}
              </button>
            );
          })}
        </div>
        {showFooter ? (
          <div className="flex items-center justify-between gap-2">
            <p className="text-body-small text-fg-secondary">{summary}</p>
            <div className="flex items-center gap-2">
              <button type="button" onClick={onCancel} className="inline-flex shrink-0 cursor-pointer select-none items-center justify-center whitespace-nowrap transition-colors disabled:pointer-events-none disabled:cursor-not-allowed [&_svg]:pointer-events-none [&_svg]:shrink-0 focus-visible:outline-none focus-visible:ring-3 focus-visible:ring-line-focus rounded-md h-8 px-3 gap-1-5 text-label-small border border-line-default bg-surface text-fg-primary hover:bg-subtle hover:border-line-strong active:bg-muted disabled:bg-disabled disabled:text-fg-disabled">
                Cancel
              </button>
              <button type="button" disabled={!current.from} onClick={() => onApply?.(current)} className="inline-flex shrink-0 cursor-pointer select-none items-center justify-center whitespace-nowrap transition-colors disabled:pointer-events-none disabled:cursor-not-allowed [&_svg]:pointer-events-none [&_svg]:shrink-0 focus-visible:outline-none focus-visible:ring-3 focus-visible:ring-line-focus rounded-md h-8 px-3 gap-1-5 text-label-small bg-brand text-fg-on-brand hover:bg-brand-hover active:bg-brand-pressed disabled:bg-disabled disabled:text-fg-disabled skin-solid">
                Apply
              </button>
            </div>
          </div>
        ) : null}
      </div>
    );
  },
);
DatePicker.displayName = "DatePicker";

export { DatePicker, datePickerVariants };
